def lowest_set_bit(idx: int) -> int:
    if idx <= 0:
        raise ValueError('Fenwick Tree indices must be >= 1')
    return idx & -idx

class FenwickTree:
    def __init__(self, n: int):
        if n <= 0:
            raise ValueError('n must be positive')
        self.n = n
        self.tree = [0] * (n + 1)

    def add(self, idx: int, delta: int) -> None:
        if not (1 <= idx <= self.n):
            raise IndexError('idx out of [1, n]')
        while idx <= self.n:
            self.tree[idx] += delta
            idx += idx & -idx

    def prefix_sum(self, idx: int) -> int:
        total = 0
        while idx > 0:
            total += self.tree[idx]
            idx -= idx & -idx
        return total

def build_linear_bit(arr: list[int]) -> list[int]:
    n = len(arr)
    tree = [0] + list(arr)
    for i in range(1, n + 1):
        parent = i + (i & -i)
        if parent <= n:
            tree[parent] += tree[i]
    return tree

def range_add_point_query(bit: FenwickTree, l: int, r: int, val: int) -> None:
    if l > r or l < 1 or r > bit.n:
        raise ValueError('Invalid range [l, r]')
    bit.add(l, val)
    if r + 1 <= bit.n:
        bit.add(r + 1, -val)

class DualFenwick:
    def __init__(self, n: int):
        self.b1 = FenwickTree(n)
        self.b2 = FenwickTree(n)

    def range_add(self, l: int, r: int, v: int) -> None:
        self.b1.add(l, v)
        self.b2.add(l, (l - 1) * v)
        if r + 1 <= self.b1.n:
            self.b1.add(r + 1, -v)
            self.b2.add(r + 1, -r * v)

    def prefix_sum(self, r: int) -> int:
        return r * self.b1.prefix_sum(r) - self.b2.prefix_sum(r)

def kth_order_statistic(tree: list[int], n: int, k: int) -> int:
    if k <= 0:
        raise ValueError('k must be >= 1')
    pos = 0
    acc = 0
    step = 1 << (n.bit_length() - 1)
    while step > 0:
        nxt = pos + step
        if nxt <= n and acc + tree[nxt] < k:
            pos = nxt
            acc += tree[nxt]
        step >>= 1
    return pos + 1

from bisect import bisect_left

class CoordinateCompressor:
    def __init__(self, raw_keys: list[int]):
        self.sorted_unique = sorted(set(raw_keys))

    def to_bit_index(self, key: int) -> int:
        idx = bisect_left(self.sorted_unique, key)
        if idx >= len(self.sorted_unique) or self.sorted_unique[idx] != key:
            raise KeyError(f'Unknown key {key}')
        return idx + 1
